mandatory_fields:
JSON METADATA SCHEMA FOR AI EXTRACTION: <br>AI harus mengekstrak data ke dalam struktur JSON berikut untuk audit:<br>{
  "document_identity": {
    "doc_name_or_type": "string",
    "doc_number_or_ref": "string",
    "execution_or_issue_date": "date/string",
    "expiry_or_validity_date": "date/string",
    "scope_or_location": "string",
    "authorized_signatory_name": "string",
    "authorized_signatory_title": "string",
    "is_signature_detected": "boolean"
  },
  "quantitative_metrics": {
    "total_target": "integer",
    "total_actual": "integer",
    "achievement_percentage": "float"
  },
  "qualitative_checks": {
    "key_topics_or_agendas_found": "array of strings",
    "compliance_coverage_percentage": "float"
  },
  "verification_evidence": {
    "has_attendance_list_signed": "boolean",
    "has_supporting_photos": "boolean",
    "has_supporting_delegation_or_authority": "boolean",
    "action_items_or_findings": "array of strings"
  }
}.<br>Contoh:
{
  "document_identity": {
    "doc_name_or_type": "Kebijakan Mutu, Keselamatan Kesehatan Kerja dan Lingkungan serta Keamanan",
    "doc_number_or_ref": "K/LSM/01 (Revisi 09) & Bukti Review Manual 2025",
    "execution_or_issue_date": "2023-10-02",
    "expiry_or_validity_date": "continuous",
    "scope_or_location": "Seluruh wilayah operasional kantor pusat dan armada kapal",
    "authorized_signatory_name": "Eddy K. Logam & Ragil Marzuki",
    "authorized_signatory_title": "Presiden Direktur & Direktur Utama",
    "is_signature_detected": true
  },
  "quantitative_metrics": {
    "total_target": 1,
    "total_actual": 1,
    "achievement_percentage": 100.0
  },
  "qualitative_checks": {
    "key_topics_or_agendas_found": [
      "Sistem Manajemen Mutu dan K3LL",
      "Larangan Penggunaan Narkoba, Obat Terlarang & Alkohol (Poin 15)",
      "Pemberantasan Tindakan Kekerasan dan Pelecehan",
      "Kepatuhan Hukum dan Regulasi Kemaritiman"
    ],
    "compliance_coverage_percentage": 100.0
  },
  "verification_evidence": {
    "has_attendance_list_signed": true,
    "has_supporting_photos": true,
    "has_supporting_delegation_or_authority": true,
    "action_items_or_findings": [
      "Kebijakan MK3LK masih sangat relevan dan sesuai dengan perkembangan industri terbaru",
      "Tidak diperlukan adanya revisi atau perbaikan dokumen utama untuk periode tahun berjalan"
    ]
  }
}
